{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.FINAL_SKU_MASTER AS with lisitng as (select upper(coalesce(UM.commonskucode,UM1.commonskucode, replace(PL.SELLER_SKU_On_CHANNEL,\' \',\'\'))) COMMONSKU ,coalesce(case when lower(Channel_Code) like \'%amazon%\' then replace(PL.SELLER_SKU_On_CHANNEL,\' \',\'\') else upper(replace(PL.SKU_Code,\' \',\'\')) end, UM.UniwareSkUCode) MARKETPLACE_SKU , upper(Channel_Code) MARKETPLACE ,Channel_Product_Id from maplemonk.KA_unicommerce_get_product_listing PL full outer join (select COMMONSKUCODE ,UniwareSkUCode from `MapleMonk.KA_GS_SKU_Uniware_Mapping` qualify row_number() over (partition by upper(UniwareSkUCode) order by 1) = 1 ) UM on lower(replace(PL.SKU_Code,\' \',\'\')) = lower(replace(UM.UniwareSkUCode,\' \',\'\')) left join (select COMMONSKUCODE ,UniwareSkUCode from `MapleMonk.KA_GS_SKU_Uniware_Mapping` qualify row_number() over (partition by upper(UniwareSkUCode) order by 1) =1 ) UM1 on lower(replace(PL.SELLER_SKU_On_CHANNEL,\' \',\'\')) = lower(replace(UM1.UniwareSkUCode,\' \',\'\')) qualify row_number() over (partition by Upper(Channel_Code), upper(coalesce(case when lower(Channel_Code) like \'%amazon%\' then replace(PL.SELLER_SKU_On_CHANNEL,\' \',\'\') else upper(replace(PL.SKU_Code,\' \',\'\')) end, UM.UniwareSkUCode)) order by 1 desc) =1 ) , COMMONSKU_MASTER as ( SELECT UPPER(coalesce(SM.Product_Name, UPM.Name)) as NAME, UPPER(COLOR) as colour, UPPER(BRAND) as BRAND, UPPER(SM.Group) as CATEGORY, UPPER(SM.Category) as Category_Code, UPPER(SM.commonskucode) as commonsku_master, SAFE_CAST(SM.MRP AS FLOAT64) as MRP, coalesce(SAFE_CAST(GST AS FLOAT64)/100,SAFE_CAST(IF( ARRAY_LENGTH(SPLIT(GST_Tax_Type_Code, \'-\')) > 1, SPLIT(GST_Tax_Type_Code, \'-\')[OFFSET(1)], NULL ) AS FLOAT64 )/100) as TAX_RATE, coalesce(SAFE_CAST(SM.Grammage as FLOAT64),SAFE_CAST(Weight__gms_ AS FLOAT64)) as weight, coalesce(SAFE_CAST(SM.Length AS FLOAT64), SAFE_CAST(Length__mm_ AS FLOAT64)) as length, coalesce(SAFE_CAST(Breadth_Dia AS FLOAT64), SAFE_CAST(Width__mm_ AS FLOAT64)) as width, ( coalesce(SAFE_CAST(SM.Length AS FLOAT64), SAFE_CAST(Length__mm_ AS FLOAT64)) * coalesce(SAFE_CAST(SM.Height AS FLOAT64), SAFE_CAST(Height__mm_ AS FLOAT64)) * coalesce(SAFE_CAST(Breadth_Dia AS FLOAT64), SAFE_CAST(Width__mm_ AS FLOAT64)) ) / 1000 as volume, SAFE_CAST(Packing AS FLOAT64) Packing_Weight, SAFE_CAST(Gross_Weight_Including_packaging_weight AS FLOAT64) Weight_Incl_Packing, SM.HSN HSN_CODE FROM (select * from `MapleMonk.KA_GS_SKU_MASTER` qualify ROW_NUMBER() OVER (PARTITION BY COMMONSKUCODE ORDER BY length(ifnull(COMMONSKUCODE,\'\')) desc) = 1) SM LEFT JOIN (select * from maplemonk.KA_unicommerce_get_product_master qualify ROW_NUMBER() OVER (PARTITION BY upper(replace(Product_Code,\' \',\'\')) ORDER BY 1) = 1 ) UPM on upper(replace(UPM.Product_Code,\' \',\'\')) = upper(SM.COMMONSKUCODE) ) select coalesce(l.COMMONSKU,cm.commonsku_master) as COMMONSKU ,l.MARKETPLACE_SKU ,l.MARKETPLACE ,l.Channel_Product_Id ,cm.* from lisitng l Full Outer join COMMONSKU_MASTER CM on upper(l.commonsku) = upper(cm.commonsku_master);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

